arguments.content:
{
  "watches": [
    {
      "description": "Create, counter, and basic display",
      "targets": [
        "new-todo.feature:Create a new todo",
        "new-todo.feature:Reject empty input",
        "new-todo.feature:Reject whitespace-only input",
        "counter.feature:Display active count with correct pluralization",
        "counter.feature:Display singular for one active todo",
        "counter.feature:Counter updates when a todo is completed"
      ]
    },
    {
      "description": "Complete and toggle todo state",
      "targets": [
        "complete-todo.feature:Mark a todo complete",
        "complete-todo.feature:Mark a completed todo as active",
        "complete-todo.feature:Mark all as complete",
        "complete-todo.feature:Mark all checkbox reflects individual state"
      ]
    },
    {
      "description": "Delete todos and empty-state visibility",
      "targets": [
        "delete-todo.feature:Delete a todo with the destroy button",
        "delete-todo.feature:Clear completed removes all completed todos",
        "delete-todo.feature:Clear completed button is hidden when no completed todos",
        "delete-todo.feature:Hide main and footer when no todos remain"
      ]
    },
    {
      "description": "Edit todo lifecycle",
      "targets": [
        "edit-todo.feature:Enter edit mode by double-clicking the label",
        "edit-todo.feature:Save edit on Enter",
        "edit-todo.feature:Save edit on blur",
        "edit-todo.feature:Discard edit on Escape",
        "edit-todo.feature:Empty edit destroys the todo"
      ]
    },
    {
      "description": "Persist todos across reloads",
      "targets": [
        "persist-todos.feature:Todos persist to localStorage",
        "persist-todos.feature:Completed state persists",
        "persist-todos.feature:Editing mode is not persisted"
      ]
    },
    {
      "description": "Filter todos by route",
      "targets": [
        "filter-todos.feature:Show all todos by default",
        "filter-todos.feature:Filter to active todos",
        "filter-todos.feature:Filter to completed todos",
        "filter-todos.feature:Filter persists on reload"
      ]
    }
  ]
}

arguments.command:
cd /home/exedev/shipshape-shakedown/.eval-scratch/todomvc-qwen/sim && echo "=== Step order validation ===" && for f in features/*.feature; do awk '
/Scenario:/{
  name=$0
  seen_given=0; seen_when=0; seen_then=0; phase=""
}
/^  +Given/{if(seen_when||seen_then) print FILENAME": "name" -> Given after When/Then"}
/^  +When/{if(seen_then) print FILENAME": "name" -> When after Then"; seen_then=0}
/^  +Then/{seen_then=1}
/Scenario:/{seen_given=0; seen_when=0; seen_then=0}
/  +Given/{seen_given=1}
/  +When/{seen_when=1}
/  +Then/{seen_then=1}
' "$f"; done && echo "All step orders valid." && echo && echo "=== Working tree status ===" && git status --short
